package io.github.ningpp.compat;

import java.util.Arrays;

/**
 * Lightweight ReadOnlyMemory&lt;T&gt; equivalent (generated by CSharpToJava converter).
 * Backed by either a String (for char memory) or a T[] array slice.
 * Does not simulate C# memory lifetime semantics.
 */
public final class ReadOnlyMemory<T> {
    /** Backing storage: a String (char memory) or a T[] array; null for default/empty. */
    private final Object backing;
    private final int start;
    private final int length;

    /** Default (empty) memory — corresponds to C# default(ReadOnlyMemory&lt;T&gt;). */
    public ReadOnlyMemory() {
        this.backing = null;
        this.start = 0;
        this.length = 0;
    }

    /** Mirrors ReadOnlyMemory&lt;T&gt;.Empty. */
    @SuppressWarnings("rawtypes")
    public static final ReadOnlyMemory Empty = new ReadOnlyMemory<>();

    /** Mirrors ReadOnlyMemory&lt;T&gt;.Empty as a generated static getter call. */
    @SuppressWarnings("unchecked")
    public static <T> ReadOnlyMemory<T> getEmpty() {
        return Empty;
    }

    public ReadOnlyMemory(T[] array) {
        this(array, 0, array == null ? 0 : array.length);
    }

    /** Copy constructor — allows re-wrapping a ReadOnlyMemory without type inference issues. */
    public ReadOnlyMemory(ReadOnlyMemory<T> other) {
        this.backing = other.backing;
        this.start = other.start;
        this.length = other.length;
    }

    public ReadOnlyMemory(T[] array, int start, int length) {
        if (array == null) {
            if (start != 0 || length != 0) {
                throw new IndexOutOfBoundsException("start=" + start + ", length=" + length);
            }
            this.backing = null;
            this.start = 0;
            this.length = 0;
            return;
        }
        if (start < 0 || length < 0 || start + length > array.length) {
            throw new IndexOutOfBoundsException(
                "start=" + start + ", length=" + length + ", arrayLength=" + array.length);
        }
        this.backing = array;
        this.start = start;
        this.length = length;
    }

    private ReadOnlyMemory(Object backing, int start, int length) {
        this.backing = backing;
        this.start = start;
        this.length = length;
    }

    /** Creates a char memory over a whole string — corresponds to string.AsMemory(). */
    public static ReadOnlyMemory<Character> fromString(String s) {
        if (s == null || s.isEmpty()) {
            return new ReadOnlyMemory<>();
        }
        return new ReadOnlyMemory<>(s, 0, s.length());
    }

    /** Creates a char memory over a string region — corresponds to string.AsMemory(start, length). */
    public static ReadOnlyMemory<Character> fromString(String s, int start, int length) {
        if (s == null) {
            if (start != 0 || length != 0) {
                throw new IndexOutOfBoundsException("start=" + start + ", length=" + length);
            }
            return new ReadOnlyMemory<>();
        }
        if (start < 0 || length < 0 || start + length > s.length()) {
            throw new IndexOutOfBoundsException(
                "start=" + start + ", length=" + length + ", stringLength=" + s.length());
        }
        if (length == 0) {
            return new ReadOnlyMemory<>();
        }
        return new ReadOnlyMemory<>(s, start, length);
    }

    public int length() {
        return length;
    }

    /** Alias for length() — matches C# ReadOnlyMemory.Length property getter translation */
    public int getLength() {
        return length;
    }

    public boolean isEmpty() {
        return length == 0;
    }

    /** Alias for isEmpty() — matches C# ReadOnlyMemory.IsEmpty property getter translation */
    public boolean getIsEmpty() {
        return length == 0;
    }

    public ReadOnlySpan<T> getSpan() {
        if (backing instanceof String s) {
            @SuppressWarnings("unchecked")
            T[] chars = (T[]) new Character[length];
            for (int i = 0; i < length; i++) {
                chars[i] = (T) Character.valueOf(s.charAt(start + i));
            }
            return new ReadOnlySpan<>(chars);
        }
        if (backing == null) {
            @SuppressWarnings("unchecked")
            T[] empty = (T[]) new Object[0];
            return new ReadOnlySpan<>(empty);
        }
        @SuppressWarnings("unchecked")
        T[] array = (T[]) backing;
        return new ReadOnlySpan<>(array, start, length);
    }

    public ReadOnlyMemory<T> slice(int sliceStart) {
        return slice(sliceStart, length - sliceStart);
    }

    public ReadOnlyMemory<T> slice(int sliceStart, int sliceLength) {
        if (sliceStart < 0 || sliceLength < 0 || sliceStart + sliceLength > length) {
            throw new IndexOutOfBoundsException(
                "start=" + sliceStart + ", length=" + sliceLength + ", memoryLength=" + length);
        }
        if (sliceLength == 0) {
            return new ReadOnlyMemory<>();
        }
        return new ReadOnlyMemory<>(backing, start + sliceStart, sliceLength);
    }

    public T[] toArray() {
        if (backing instanceof String s) {
            @SuppressWarnings("unchecked")
            T[] chars = (T[]) new Character[length];
            for (int i = 0; i < length; i++) {
                chars[i] = (T) Character.valueOf(s.charAt(start + i));
            }
            return chars;
        }
        if (backing == null) {
            @SuppressWarnings("unchecked")
            T[] empty = (T[]) new Object[0];
            return empty;
        }
        @SuppressWarnings("unchecked")
        T[] array = (T[]) backing;
        return Arrays.copyOfRange(array, start, start + length);
    }

    @Override
    public String toString() {
        if (backing instanceof String s) {
            return s.substring(start, start + length);
        }
        if (backing instanceof Character[] chars) {
            StringBuilder sb = new StringBuilder(length);
            for (int i = 0; i < length; i++) {
                sb.append(chars[start + i]);
            }
            return sb.toString();
        }
        return super.toString();
    }
}
